"        function getWorkflowProgress(asset, mode) {
            try {
                const data = JSON.parse(localStorage.getItem('rivenquant_workflow_progress_v3') || '{}');
                if (!data[asset]) data[asset] = { ai: 0, custom: 0 };

                if (data[asset][mode] === undefined) {
                    data[asset][mode] = 0;
                    localStorage.setItem('rivenquant_workflow_progress_v3', JSON.stringify(data));
                }

                return data[asset][mode];
            } catch (e) {
                return 0;
            }
        }

        function saveWorkflowProgress(asset, mode, step) {
            try {
                const data = JSON.parse(localStorage.getItem('rivenquant_workflow_progress_v3') || '{}');
                if (!data[asset]) data[asset] = { ai: 0, custom: 0 };
                data[asset][mode] = step;
                localStorage.setItem('rivenquant_workflow_progress_v3', JSON.stringify(data));
            } catch (e) {}
        }

        function resetWorkflowProgress() {
            if (confirm("Вы уверены, что хотите сбросить прогресс по этому активу?")) {
                saveWorkflowProgress(activeAsset, quickStartMode, 0);
                renderWorkflowTimeline(activeAsset);
                showActionToast("Прогресс сброшен.");
            }
        }"

